-- Fixture for the data-fix + unique-index DB tests (run-payroll-no-double-pay.sh, F*).
-- A small copy of the prod shape on 2026-10-21. Ids: a=period, b=snapshot, c=job, d=user.
--   j14 (c14): 2026-30 + W31, two roles; state -> W31            => delete W31 copy (2 lines)
--   j17 (c17): 2026-30 + W31 + w32, one role; state -> w32        => delete W31 + w32 copies
--   j29 (c29): w32 + W33, W33's snapshot CREATED FIRST; state -> w32
--              => keep w32 (earliest by cutoff, not by creation); state untouched
--   j00 (c00): paid once in W29 (not a duplicate)    j34 (c34): once in W34
-- Expected: 4 snapshots / 5 lines removed, net 3249.97, 2 state rows repointed.
\set ON_ERROR_STOP 1
DO $$ BEGIN
  IF current_database() NOT LIKE 'payroll_guard_test_%' THEN
    RAISE EXCEPTION 'refusing to run outside a payroll_guard_test_* database (got %)', current_database();
  END IF;
END $$;
\ir payroll_test_schema.sql

