INSERT INTO payroll_payout_lines (org_id, payroll_period_id, payroll_job_snapshot_id, job_id, user_id, participant_role, gross_amount, net_amount)
SELECT s.org_id, s.payroll_period_id, s.id, s.job_id, v.user_id::uuid, v.role, v.amt, v.amt
FROM payroll_job_snapshots s
JOIN (VALUES
  ('00000000-0000-0000-0000-000000000c14','00000000-0000-0000-0000-0000000000d1','sales_rep',1000.00),
  ('00000000-0000-0000-0000-000000000c14','00000000-0000-0000-0000-0000000000d2','setter',    132.26),
  ('00000000-0000-0000-0000-000000000c17','00000000-0000-0000-0000-0000000000d1','sales_rep', 876.67),
  ('00000000-0000-0000-0000-000000000c29','00000000-0000-0000-0000-0000000000d1','sales_rep', 364.37),
  ('00000000-0000-0000-0000-000000000c00','00000000-0000-0000-0000-0000000000d1','sales_rep', 500.00),
  ('00000000-0000-0000-0000-000000000c34','00000000-0000-0000-0000-0000000000d1','sales_rep', 250.00)
) v(job_id, user_id, role, amt) ON v.job_id::uuid = s.job_id;

